// ---------- helpers ----------
const brl = (n) =>
  (Number(n) || 0).toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
const today = new Date();
const fmtDate = (d) => d.toLocaleDateString("pt-BR");
const fmtTime = (d) => d.toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" });
const norm = (s) => (s || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
const uid = (() => { let n = 1000; return () => n++; })();
const addDays = (isoDate, n) => {
  const d = new Date(isoDate + "T00:00:00");
  d.setDate(d.getDate() + Number(n));
  return d.toISOString().slice(0, 10);
};
const diasRestantes = (vencIso) => Math.ceil((new Date(vencIso + "T00:00:00") - today) / 86400000);
const corVencimento = (dias) => {
  if (dias <= 5) return { bg: "#FBE8E6", color: "#B3261E", label: "danger" };
  if (dias <= 15) return { bg: "#F6EBDA", color: "#A66A1E", label: "warn" };
  return { bg: "#E6F0EA", color: "#2F6B4F", label: "success" };
};
