// ---------- small UI atoms ----------
function Toast({ toasts }) {
  return (
    <div style={{ position: "fixed", bottom: 20, right: 20, zIndex: 200, display: "flex", flexDirection: "column", gap: 8 }}>
      {toasts.map((t) => (
        <div key={t.id} style={{
          background: t.type === "error" ? "#B3261E" : "#2F6B4F",
          color: "#fff", padding: "10px 16px", borderRadius: 6, fontSize: 13.5,
          boxShadow: "0 4px 14px rgba(0,0,0,.18)", minWidth: 220,
        }}>{t.message}</div>
      ))}
    </div>
  );
}

function Badge({ children, tone = "neutral" }) {
  const tones = {
    neutral: { bg: "#EDECE8", color: "#23231F" },
    danger: { bg: "#FBE8E6", color: "#B3261E" },
    success: { bg: "#E6F0EA", color: "#2F6B4F" },
    warn: { bg: "#F6EBDA", color: "#A66A1E" },
  };
  const s = tones[tone];
  return (
    <span style={{ background: s.bg, color: s.color, fontSize: 12, padding: "3px 9px", borderRadius: 20, fontWeight: 600 }}>
      {children}
    </span>
  );
}

function Modal({ title, onClose, children, width = 480 }) {
  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(28,28,26,.45)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 150 }} onClick={onClose}>
      <div style={{ background: "#fff", borderRadius: 8, width, maxWidth: "92vw", maxHeight: "88vh", overflow: "auto", boxShadow: "0 20px 60px rgba(0,0,0,.25)" }} onClick={(e) => e.stopPropagation()}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "16px 20px", borderBottom: "1px solid #E1DDD3" }}>
          <h3 style={{ margin: 0, fontSize: 16, fontWeight: 700, color: "#23231F" }}>{title}</h3>
          <button onClick={onClose} style={{ background: "none", border: "none", cursor: "pointer", color: "#23231F" }}><X size={18} /></button>
        </div>
        <div style={{ padding: 20 }}>{children}</div>
      </div>
    </div>
  );
}

function Row({ label, value, bold }) {
  return (
    <div style={{ display: "flex", justifyContent: "space-between", padding: "3px 0", fontSize: 13, fontWeight: bold ? 700 : 400 }}>
      <span style={{ color: "#23231F" }}>{label}</span>
      <span style={{ color: "#23231F" }}>{value}</span>
    </div>
  );
}
function Field({ label, children }) {
  return (
    <label style={{ display: "block", marginBottom: 12 }}>
      <div style={{ fontSize: 12.5, color: "#23231F", marginBottom: 5, fontWeight: 600 }}>{label}</div>
      {children}
    </label>
  );
}
