// ================= APP =================
export default function AppShell({
  initialProducts, initialCustomers, initialSuppliers, initialPayables,
  initialSales, initialCrediario, initialCaixa,
}) {
  const [screen, setScreen] = useState("pdv");
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [toasts, setToasts] = useState([]);
  const [dismissedNotifs, setDismissedNotifs] = useState([]);
  const pushToast = (message, type = "success") => {
    const id = uid();
    setToasts((t) => [...t, { id, message, type }]);
    setTimeout(() => setToasts((t) => t.filter((x) => x.id !== id)), 3200);
  };

  // data
  const [products, setProducts] = useState(initialProducts && initialProducts.length ? initialProducts : seedProducts);
  const [customers, setCustomers] = useState(initialCustomers && initialCustomers.length ? initialCustomers : seedCustomers);
  const [suppliers, setSuppliers] = useState(initialSuppliers && initialSuppliers.length ? initialSuppliers : seedSuppliers);
  const [payables, setPayables] = useState(initialPayables && initialPayables.length ? initialPayables : seedPayables);
  const [sales, setSales] = useState(initialSales && initialSales.length ? initialSales : seedSales);
  const [crediario, setCrediario] = useState(initialCrediario || []);
  const [caixa, setCaixa] = useState(initialCaixa || { aberto: false, valorInicial: 0, sangrias: [] });

  useEffect(() => {
    const vencendo = payables.filter((p) => {
      if (p.status !== "Pendente") return false;
      const dias = (new Date(p.vencimento) - today) / 86400000;
      return dias <= 5;
    });
    if (vencendo.length > 0) {
      pushToast("Lembrete: Você tem contas a vencer, verifique em formas de pagamentos", "error");
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const excluirVenda = async (sale) => {
    try {
      await excluirVendaAcao(sale.id);
      setSales((s) => s.filter((x) => x.id !== sale.id));
      setProducts((ps) => ps.map((p) => {
        const item = sale.itens.find((i) => i.produtoId === p.id);
        return item ? { ...p, estoque: p.estoque + item.qtd } : p;
      }));
      setCrediario((cr) => cr.filter((c) => c.vendaId !== sale.id));
      pushToast("Venda excluída e estoque devolvido");
    } catch (e) {
      pushToast("Erro ao excluir a venda", "error");
    }
  };

  const notificacoesVencimento = crediario.filter((c) =>
    c.status === "Pendente" && c.vencimento && diasRestantes(c.vencimento) <= 2 && !dismissedNotifs.includes(c.id)
  );

  const navGroups = [
    {
      title: "Operação",
      items: [
        { id: "pdv", label: "PDV / Vendas", icon: ShoppingCart },
        { id: "estoque", label: "Estoque", icon: Package },
        { id: "diario", label: "Faturamento do Dia", icon: TrendingUp },
        { id: "crediario", label: "Promissórias", icon: CreditCard },
        { id: "dashboard", label: "Faturamento Mensal", icon: BarChart2 },
      ],
    },
    {
      title: "Relacionamento",
      items: [
        { id: "clientes", label: "Clientes", icon: Users },
        { id: "fornecedores", label: "Fornecedores", icon: Truck },
      ],
    },
    {
      title: "Gestão",
      items: [
        { id: "financeiro", label: "Contas a Pagar", icon: Wallet },
        { id: "relatorios", label: "Relatórios", icon: FileText },
      ],
    },
  ];

  return (
    <div style={{ display: "flex", minHeight: "100vh", background: "#F6F6F4", fontFamily: "'IBM Plex Sans', ui-sans-serif, system-ui, sans-serif" }}>
      <style>{`
        * { font-variant-numeric: tabular-nums; }
        @import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600;700&display=swap');
        button:hover { opacity: .92; }
        table { border-collapse: collapse; width: 100%; }
        @keyframes slideInNotif { from { opacity: 0; transform: translateX(24px); } to { opacity: 1; transform: translateX(0); } }
        .print-only-header { display: none; }
        @media print {
          body * { visibility: hidden; }
          .print-area, .print-area * { visibility: visible; }
          .print-area { position: absolute; left: 0; top: 0; width: 100%; padding: 24px; background: #fff; }
          .print-only-header { display: block; }
          table, th, td { border: 1px solid #000 !important; }
        }
      `}</style>
      <Toast toasts={toasts} />
      {notificacoesVencimento.length > 0 && (
        <div style={{ position: "fixed", top: 18, right: 18, zIndex: 190, display: "flex", flexDirection: "column", gap: 10, maxWidth: 320 }}>
          {notificacoesVencimento.map((c) => {
            const dias = diasRestantes(c.vencimento);
            return (
              <div key={c.id} style={{
                background: "#fff", border: "2px solid #B3261E", borderRadius: 10, padding: "12px 14px",
                boxShadow: "0 8px 24px rgba(0,0,0,.14)", animation: "slideInNotif .25s ease-out",
              }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 10 }}>
                  <div style={{ display: "flex", gap: 8, alignItems: "flex-start" }}>
                    <AlertTriangle size={16} style={{ color: "#B3261E", flexShrink: 0, marginTop: 2 }} />
                    <div>
                      <div style={{ fontSize: 13, fontWeight: 700, color: "#23231F" }}>Promissória vencendo</div>
                      <div style={{ fontSize: 12.5, color: "#23231F", marginTop: 2 }}>{c.clienteNome} — {brl(c.saldo)}</div>
                      <div style={{ fontSize: 12, color: "#B3261E", marginTop: 2, fontWeight: 600 }}>
                        {dias < 0 ? `Vencida há ${Math.abs(dias)} dia(s)` : dias === 0 ? "Vence hoje" : `Vence em ${dias} dia(s)`}
                      </div>
                    </div>
                  </div>
                  <button onClick={() => setDismissedNotifs((d) => [...d, c.id])} style={{ background: "none", border: "none", cursor: "pointer", color: "#23231F", flexShrink: 0 }}><X size={15} /></button>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* sidebar */}
      <div style={{ width: sidebarCollapsed ? 76 : 232, background: "#16211C", color: "#EFEFEC", display: "flex", flexDirection: "column", flexShrink: 0, transition: "width .15s ease" }}>
        <div style={{ padding: sidebarCollapsed ? "18px 10px 12px" : "18px 18px 12px", borderBottom: "1px solid #24332C" }}>
          <img src={LOGO} alt="Papelaria Moura" style={{ width: "100%", maxWidth: sidebarCollapsed ? 40 : 70, display: "block", margin: "0 auto 8px" }} />
          {!sidebarCollapsed && (
            <div style={{ fontSize: 11.5, color: "#9FB0A5", textAlign: "center" }}>
              {caixa.aberto ? <span style={{ color: "#8FD4A8" }}>● Caixa aberto</span> : <span style={{ color: "#E0938C" }}>● Caixa fechado</span>}
            </div>
          )}
        </div>

        <div style={{ flex: 1, padding: "14px 10px", overflowY: "auto" }}>
          {navGroups.map((group) => (
            <div key={group.title} style={{ marginBottom: 18 }}>
              {!sidebarCollapsed && (
                <div style={{ fontSize: 10.5, letterSpacing: .6, color: "#7C9385", fontWeight: 700, padding: "0 10px 6px", textTransform: "uppercase" }}>
                  {group.title}
                </div>
              )}
              {group.items.map((n) => {
                const Icon = n.icon;
                const active = screen === n.id;
                return (
                  <div key={n.id} onClick={() => setScreen(n.id)} title={sidebarCollapsed ? n.label : undefined} style={{
                    display: "flex", alignItems: "center", gap: 11,
                    padding: sidebarCollapsed ? "10px 0" : "10px 12px",
                    justifyContent: sidebarCollapsed ? "center" : "flex-start",
                    borderRadius: 10, cursor: "pointer", marginBottom: 3, fontSize: 13.5,
                    background: active ? "linear-gradient(90deg, #2F6B4F, #24543E)" : "transparent",
                    color: active ? "#fff" : "#C4D0C9",
                  }}>
                    <Icon size={16} style={{ flexShrink: 0 }} /> {!sidebarCollapsed && n.label}
                  </div>
                );
              })}
            </div>
          ))}
        </div>

        <div style={{ padding: 12, borderTop: "1px solid #24332C", display: "flex", gap: 8 }}>
          <div onClick={() => signOut({ callbackUrl: "/login" })} style={{
            flex: 1, display: "flex", alignItems: "center", justifyContent: "center", gap: 8, cursor: "pointer",
            color: "#EFEFEC", fontSize: 13.5, padding: "10px 0", borderRadius: 10, background: "#1D2B24", border: "1px solid #2E4038",
          }}>
            <LogOut size={15} /> {!sidebarCollapsed && "Sair"}
          </div>
          <button onClick={() => setSidebarCollapsed((c) => !c)} title={sidebarCollapsed ? "Expandir menu" : "Recolher menu"} style={{
            width: 40, flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center",
            borderRadius: 10, background: "#1D2B24", border: "1px solid #2E4038", color: "#EFEFEC", cursor: "pointer",
          }}>
            <Menu size={16} />
          </button>
        </div>
      </div>

      {/* main */}
      <div className="app-content" style={{ flex: 1, display: "flex", flexDirection: "column", minWidth: 0 }}>
        <div style={{ padding: "26px 32px", flex: 1, overflow: "auto" }}>
          {screen === "pdv" && (
            <PDV {...{ products, setProducts, customers, setCustomers, sales, setSales, caixa, setCaixa, crediario, setCrediario, excluirVenda, pushToast }} />
          )}
          {screen === "estoque" && <Estoque {...{ products, setProducts, pushToast }} />}
          {screen === "clientes" && <Clientes {...{ customers, setCustomers, pushToast }} />}
          {screen === "fornecedores" && <Fornecedores {...{ suppliers, setSuppliers, pushToast }} />}
          {screen === "financeiro" && <Financeiro {...{ payables, setPayables, sales, pushToast }} />}
          {screen === "crediario" && <Crediario {...{ crediario, setCrediario, sales, customers, pushToast }} />}
          {screen === "diario" && <FaturamentoDia {...{ sales, caixa, crediario, excluirVenda }} />}
          {screen === "dashboard" && <DashboardMensal {...{ sales, products, payables, customers, crediario }} />}
          {screen === "relatorios" && <Relatorios {...{ sales, products, customers, payables }} />}
        </div>
        <div style={{ padding: "10px 32px", fontSize: 11.5, color: "#96938A", borderTop: "1px solid #E1DDD3" }}>
          Desenvolvido por Deivid Lima ©
        </div>
      </div>
    </div>
  );
}

